  {
    "Name": "Login",
    "ResourceKey": "Account",
    "Key": "Account",
    "Content": "<div class="row justify-content-center"><div class="col-12 col-sm-8 col-md-5 col-lg-4"><div class="login-container p-4" name="Login"><h2 class="p-0">[resource_displayname[signin]]</h2><div class="input-group input-group-sm mb-3"><input type="email" name="user" class="form-control" placeholder="[resource_displayname[email]]" /></div><div class="input-group input-group-sm mb-3"><input type="password" name="pass" class="form-control" placeholder="[resource_displayname[password]]" /></div><div class="d-flex justify-content-between gap-2 mb-2"><button type="button" class="btn btn-primary btn-sm" name="forgotPass">[resource_displayname[forgotpassword]]</button><button type="button" class="btn btn-primary btn-sm" name="login">[resource_displayname[login]]</button></div><div class="d-grid"><button type="button" class="btn btn-secondary btn-sm" name="register">[resource_displayname[donthaveanaccount]]</button></div></div></div></div><script nonce="[request[nonce]]" name="ForgotPass" type="text/template"><form class="form" name="forgotPasswordForm"><div class="input-group input-group-sm mb-3"><span class="input-group-text">[resource_displayname[email]]</span><input type="email" class="form-control" name="email" required /></div><div class="text-end mt-2"><button type="button" class="btn btn-outline-secondary btn-sm" name="submit"><span class="k-icon k-i-paper-plane"></span> [resource_displayname[submit]]</button></div></form></script><div name="registerComponent" style="display:none">[component[Register]]</div>",
    "Script": "Login = {
  init: async function(app, container) {
    app = app || session.app; container = container || $("[name=Login]");
    var login = async function(e) { e.preventDefault(); notification.info("[resource_displayname[loggingin]]"); var result = await api.login($("[name=user]", container).val(), $("[name=pass]", container).val()); if (!result) { Login.failed(); return; } await Login.success(); };
    $("button[name=login]", container).off("click.login").on("click.login", login);
    $("[name=pass]", container).off("keyup.login").on("keyup.login", async function(e) { if (e.keyCode === 13) await login(e); });
    $("[name=forgotPass]", container).off("click.login").on("click.login", Login.forgotPassword);
    $("[name=register]", container).off("click.login").on("click.login", Login.register);
  },
  getRedirectUrl: function() { var redirectUrl = getQueryParameter("returnUrl") || getQueryParameter("ReturnUrl") || getQueryParameter("return") || getQueryParameter("redirect"); return redirectUrl && redirectUrl.indexOf("/") === 0 && redirectUrl.indexOf("//") !== 0 ? redirectUrl : "/"; },
  register: function(e) { e.preventDefault(); var dialog = new Dialog({ title: "[resource_displayname[register]]", width: 1350, height: 770 }); dialog.template = $("[name=registerComponent]").first().html(); dialog.init(() => Register.init(session.app, $(".component[name=Register]", dialog.element), dialog)); },
  forgotPassword: function(e) { e.preventDefault(); var dialog = new Dialog({ title: "[resource_description[PasswordResetEmailTitle]]" }); dialog.template = $("script[name=ForgotPass]").html(); dialog.events.submit = async function() { var form = $("[name=forgotPasswordForm]", dialog.element); if (form.getKendoValidator().validate()) { await api.post("Account/ForgotPassword", { Email: $("input[name=email]", form).val(), AppId: session.app.Id, Culture: session.culture }); notification.success("[resource_description[CheckYourEmail]]"); dialog.events.close(); } }; dialog.init(() => $("[name=forgotPasswordForm]", dialog.element).kendoValidator()); },
  success: async function() { window.location.replace(Login.getRedirectUrl()); },
  failed: function() { notification.error("[resource_description[AccessDenied]]"); }
};"
  }
]

